-- ================================================= Requirement ====================
-- SCRIPT DE POBLADO MASIVO Y ULTRA-REALISTA (2024 - 2026) — SIMPLIFY-BIZ
-- Genera cientos de ventas distribuidas por días, meses y años
-- ====================================================================

CREATE TABLE IF NOT EXISTS usuarios (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, telefono TEXT NOT NULL, email TEXT NOT NULL, rol INTEGER NOT NULL, contraseña TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS productos (id INTEGER PRIMARY KEY AUTOINCREMENT, producto TEXT NOT NULL, precio REAL NOT NULL, precio_costo REAL DEFAULT 0.0, cantidad INTEGER NOT NULL, codigo TEXT NOT NULL, categoria TEXT);
CREATE TABLE IF NOT EXISTS ventas (id INTEGER PRIMARY KEY AUTOINCREMENT, cliente TEXT NOT NULL, cc_cliente TEXT NOT NULL, vendedor TEXT NOT NULL, fecha DATE NOT NULL, total REAL NOT NULL, metodo_pago TEXT NOT NULL, pago_confirmado TEXT);
CREATE TABLE IF NOT EXISTS detalles_venta (id INTEGER PRIMARY KEY AUTOINCREMENT, venta_id INTEGER NOT NULL, producto TEXT NOT NULL, cantidad INTEGER NOT NULL, codigo TEXT NOT NULL, precio REAL NOT NULL, precio_costo REAL DEFAULT 0.0, descuento REAL DEFAULT 0.0, total REAL NOT NULL, FOREIGN KEY (venta_id) REFERENCES ventas(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS configuracion (id INTEGER PRIMARY KEY, ultimoNumeroCotizacion TEXT);
CREATE TABLE IF NOT EXISTS categorias (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS abonos_cartera (id INTEGER PRIMARY KEY AUTOINCREMENT, venta_id INTEGER NOT NULL, monto REAL NOT NULL, fecha DATE NOT NULL, metodo_pago TEXT NOT NULL, observacion TEXT, FOREIGN KEY (venta_id) REFERENCES ventas(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS proveedores (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, nit TEXT UNIQUE NOT NULL, telefono TEXT, email TEXT, direccion TEXT);
CREATE TABLE IF NOT EXISTS compras (id INTEGER PRIMARY KEY AUTOINCREMENT, proveedor_id INTEGER, proveedor_nombre TEXT NOT NULL, proveedor_nit TEXT NOT NULL, num_factura TEXT NOT NULL, usuario_registro TEXT NOT NULL, fecha DATE NOT NULL, total REAL NOT NULL, FOREIGN KEY (proveedor_id) REFERENCES proveedores(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS detalles_compra (id INTEGER PRIMARY KEY AUTOINCREMENT, compra_id INTEGER NOT NULL, producto TEXT NOT NULL, codigo TEXT NOT NULL, cantidad INTEGER NOT NULL, precio_costo REAL NOT NULL, subtotal REAL NOT NULL, FOREIGN KEY (compra_id) REFERENCES compras(id) ON DELETE CASCADE);

DELETE FROM abonos_cartera;
DELETE FROM detalles_compra;
DELETE FROM compras;
DELETE FROM detalles_venta;
DELETE FROM ventas;
DELETE FROM productos;
DELETE FROM proveedores;
DELETE FROM categorias;
DELETE FROM usuarios;




